begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $text$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1706 then raise exception 'ITEM_TEXT_CAMPAIGN_CONFLICT';end if;if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1292a93cfe7a65cc643acff2' and md5(to_jsonb(t)::text)='ce5f0a83b32fe01bfe1c475ca3625ce6')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:1292a93cfe7a65cc643acff2';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_3a00074e3ddfd597$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto del conjuro forma gaseosa durante 1 hora (no requiere concentración) o hasta que pongas fin al efecto como acción adicional. El frasco de esta poción parece contener una niebla que se mueve y se derrama como si fuese agua.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3a00074e3ddfd597$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1292a93cfe7a65cc643acff2';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:12dbdfe92af7a3f1f15418a0' and md5(to_jsonb(t)::text)='468f48082d85ffc4f943e30d949325f8')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:12dbdfe92af7a3f1f15418a0';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_212e7bab5e65823c$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, podrás lanzar a voluntad el conjuro salto desde él como acción adicional, pero solo podrás ser tú el objetivo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_212e7bab5e65823c$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:12dbdfe92af7a3f1f15418a0';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:162777d7c51d3223ce6c645e' and md5(to_jsonb(t)::text)='e6ebb8d88d827c707dcf141c3d8d7bed')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:162777d7c51d3223ce6c645e';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_63df192432446816$[{"id":"legacy-bonus-0","kind":"passive","name":"AC","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +1 a la CA.","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta armadura, obtendrás un bonificador de +1 a la CA. Se te considera competente con esta armadura aunque no tengas competencia con armaduras medias.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_63df192432446816$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:162777d7c51d3223ce6c645e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1690ade2e005b3d5419276d2' and md5(to_jsonb(t)::text)='f39a8765079398ad8e20805cb8b75efb')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:1690ade2e005b3d5419276d2';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_8f83b90bcdfccf65$[{"id":"mundane-assisted-use","kind":"other","name":"Contenido del paquete","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Paquete de ladrón (16 po). Incluye una mochila, una bolsa con 1000 bolas de metal, 3 m de cordel, una campana, 5 velas, una palanqueta, un martillo, 10 pitones, una linterna sorda, 2 frascos de aceite, raciones para 5 días, un yesquero y una cantimplora. Además, el paquete tiene una cuerda de cáñamo de 15 m enganchada en un lado.\n\nDuración: Según su uso..","showInActions":false}]$text_8f83b90bcdfccf65$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1690ade2e005b3d5419276d2';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:16bfcef27391210d1ed5263a' and md5(to_jsonb(t)::text)='7acdf9161b5eba646e78347662d08d27')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:16bfcef27391210d1ed5263a';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_9fceb96e5977b7f4$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, podrás utilizar una acción y gastar 1 de sus 3 cargas para lanzar el conjuro deseo desde él. El anillo se volverá no mágico cuando utilices la última carga.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_9fceb96e5977b7f4$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:16bfcef27391210d1ed5263a';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1720e219787223e70061991c' and md5(to_jsonb(t)::text)='290b43a6cf1c5a934e225d2d913803a9')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:1720e219787223e70061991c';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_708acdbfd8530f9b$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta esfera negra de 60 cm de diámetro es un agujero en el multiverso que levita en el espacio y que permanece estabilizado gracias a un campo mágico que lo rodea.\n\nLa esfera aniquila toda la materia que atraviesa y que la atraviesa. La única excepción son los artefactos, que la atravesarán intactos salvo que sean susceptibles al daño de una esfera de aniquilación. Cualquier otra cosa que toque la esfera sin ser completamente absorbida y destruida por ella sufrirá 4d10 de daño de fuerza.\n\nLa esfera permanece inmóvil hasta que alguien la controla. Si estás a 18 m o menos de una esfera no controlada, podrás utilizar una acción para realizar una prueba de Inteligencia (Conocimiento Arcano) con CD 25. Si la superas, la esfera levitará en la dirección que elijas hasta un número de metros máximo igual a 1,5 × tu modificador por Inteligencia (como mínimo 1,5 m). Si la fallas, la esfera se moverá 3 m hacia ti. Si la esfera entra en el espacio de una criatura, esta deberá superar una tirada de salvación de Destreza con CD 13 o la esfera la tocará y le infligirá 4d10 de daño de fuerza.\n\nSi tratas de controlar una esfera que se encuentre bajo el control de otra criatura, deberás realizar una prueba de Inteligencia (Conocimiento Arcano) contra la Inteligencia (Conocimiento Arcano) de la otra criatura. El vencedor se hará con el control de la esfera y podrá hacerla levitar de la manera normal.\n\nSi la esfera entra en contacto con un portal interplanar, como el que crea un conjuro portal, o un espacio extradimensional, como el que contiene un agujero portátil, tu GM determinará al azar lo que ocurrirá usando la siguiente tabla.\n\n01–50 · La esfera se destruye.\n51–85 · La esfera atraviesa el portal o entra en el espacio extradimensional.\n86–00 · Una grieta en el espacio envía a todas las criaturas y objetos que se encuentren a 54 m o menos de la esfera, incluida la esfera, a un plano de existencia aleatorio.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_708acdbfd8530f9b$::jsonb,true),'{rules,personalDescription}',$text_fb65389feb5fd1fb$"Esta esfera negra de 2 pies de diámetro es un agujero en el multiverso que levita en el espacio, estabilizado por el campo mágico que lo rodea.\n\nLa esfera aniquila toda la materia que atraviese. Los artefactos son la única excepción: a menos que un artefacto sea vulnerable al daño de una esfera de aniquilación, atraviesa la esfera intacto. Cualquier otra cosa que toque la esfera pero no sea completamente absorbida y destruida por ella recibe 4dl0 de daño de fuerza.\n\nLa esfera permanece fija hasta que alguien la controle. Si estás a 60 pies de una esfera no controlada, puedes usar una acción para hacer una prueba de Inteligencia (Conocimiento Arcano) CD 25. Si tienes éxito, la esfera levita en una dirección de tu elección hasta un número de pies máximo igual a 5 veces tu modificador por Inteligencia (mínimo 1 pie). Si fallas la prueba, la esfera se acerca 10 pies hacia ti. Una criatura en cuyo espacio entre la esfera deberá superar una tirada de salvación de Destreza CD 13 o será tocada por ella, recibiendo 4dl0 de daño de fuerza.\n\nSi quieres intentar controlar una esfera que ya está bajo el dominio de otra criatura, debes realizar una tirada enfrentada de Inteligencia (Conocimiento Arcano) contra la Inteligencia (Conocimiento Arcano) de la otra criatura. El vencedor consigue el control de la esfera y puede hacerla levitar de la manera normal.\n\nSi la esfera entra en contacto con un portal interplanar, como el creado por el conjuro portal, o un espacio extradimensional, como el de un agujero portátil, el DM determina aleatoriamente lo que pasa, utilizando la siguiente tabla.\n\n01-50 - La esfera es destruida.\n51-85 - La esfera atraviesa el portal o espacio extradimensional.\n86-00 - Una grieta en el espacio envía a todas las criaturas y objetos que se encuentren a 180 pies de la esfera, incluyendo la propia esfera, a un plano de existencia aleatorio."$text_fb65389feb5fd1fb$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1720e219787223e70061991c';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:175302cfd38f05a93c9455df' and md5(to_jsonb(t)::text)='1d3500efe205a99b3c249b6cbfcc9d74')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:175302cfd38f05a93c9455df';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_e8c326586f417af7$"Objeto · Precio base · Peso\nSuministros de calígrafo · 10 po · 5 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_e8c326586f417af7$::jsonb,true),'{features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{rules,definition,description}',$text_54f1579444fddaef$[{"id":"official-table","rows":[["Suministros de calígrafo","10 po","5 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_54f1579444fddaef$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:175302cfd38f05a93c9455df';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:17a8948e3f7bd66ba362ccbf' and md5(to_jsonb(t)::text)='dff6bb0b4d915c0ce0c5fd5dd0f7cebe')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:17a8948e3f7bd66ba362ccbf';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_01e90fa6b8e98336$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta armadura, tienes resistencia a un tipo de daño de entre los siguientes: contundente, cortante o perforante. Tu GM elige el tipo o lo determina al azar.\n\nMaldición. Esta armadura está maldita, circunstancia que solo se revela cuando se lanza el conjuro identificar sobre ella o te sintonizas con ella. Al sintonizarte con la armadura, sufres la maldición hasta que seas el objetivo del conjuro levantar maldición u otro efecto mágico similar. Quitarse la armadura no pone fin a la maldición. Mientras sufras la maldición, serás vulnerable a dos de los tres tipos de daño asociados con la armadura (salvo al que tienes resistencia gracias a la ella).\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_01e90fa6b8e98336$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:17a8948e3f7bd66ba362ccbf';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:181be68f4b1f5b75ca241809' and md5(to_jsonb(t)::text)='6995e7d4fd4e7acee0f3d6d5e8d7385f')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:181be68f4b1f5b75ca241809';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_f0a900e527c71ac1$[{"id":"legacy-bonus-0","kind":"passive","name":"AC","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +2 a la CA.","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Obtienes un bonificador a la CA mientras lleves esta armadura. El bonificador depende de su rareza.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f0a900e527c71ac1$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:181be68f4b1f5b75ca241809';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1841b81ee7964b8aa7381ead' and md5(to_jsonb(t)::text)='f95492706693e97e86e34287f2cc16fa')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:1841b81ee7964b8aa7381ead';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_fa8a9b68dee1c424$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta capa tiene un ligero aroma a azufre. Mientras la lleves puesta, podrás usarla para lanzar el conjuro puerta dimensional como acción. Esta propiedad de la capa no puede volver a usarse hasta el siguiente amanecer.\n\nCuando desapareces, dejas tras de ti una nube de humo y apareces en una nube de humo similar en tu destino. El humo hace que el espacio que abandonas y en el que apareces estén ligeramente oscurecidos, y se disipa al final de tu siguiente turno. Un viento suave o más fuerte dispersa el humo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_fa8a9b68dee1c424$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1841b81ee7964b8aa7381ead';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1979314dd959de4052e3f286' and md5(to_jsonb(t)::text)='5c33cd7c98e095d81dfce1abf2ca5198')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:1979314dd959de4052e3f286';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_82bc9fa4035dc2ac$"Objeto · Precio base · Peso\nCatalejo · 1000 po · 1 lb\n\nCatalejo. Los objetos que se observan a través de un catalejo se ven al doble de su tamaño real.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_82bc9fa4035dc2ac$::jsonb,true),'{features}',$text_07805aba52eb036e$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Catalejo. Los objetos que se observan a través de un catalejo se ven al doble de su tamaño real.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_07805aba52eb036e$::jsonb,true),'{rules,definition,description}',$text_cccc6b99237bd431$[{"id":"official-table","rows":[["Catalejo","1000 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Catalejo. Los objetos que se observan a través de un catalejo se ven al doble de su tamaño real.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_cccc6b99237bd431$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1979314dd959de4052e3f286';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1a642ca8b6c9c5446ce9f228' and md5(to_jsonb(t)::text)='0775eb428eadab6add929d0ca30a5f4f')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:1a642ca8b6c9c5446ce9f228';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_4075f39b58eb84a0$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puestas estas botas, tendrás una velocidad volando igual a tu velocidad caminando. Puedes utilizar las botas para volar durante 4 horas como máximo, ya sea de una vez o en varios vuelos más cortos, que emplearán como mínimo 1 minuto de la duración. Si estás volando cuando concluya la duración, descenderás a una velocidad de 9 m por asalto hasta que aterrices.\n\nLas botas recuperan 2 horas de vuelo por cada 12 horas que no se utilicen.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4075f39b58eb84a0$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1a642ca8b6c9c5446ce9f228';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1cc6fb29854598ed46a65f3c' and md5(to_jsonb(t)::text)='bfc80537b4e277876a94bf11e48da141')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:1cc6fb29854598ed46a65f3c';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_cfaea569d2e0b0bc$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +3 a las tiradas de ataque y de daño que hagas con esta arma mágica. Además, el arma ignora la resistencia al daño cortante.\n\nCuando ataques a una criatura que tenga al menos una cabeza con esta arma y el resultado de la tirada de ataque sea 20, cercenarás una de las cabezas de esa criatura. La criatura muere si no puede sobrevivir sin la cabeza perdida. Una criatura es inmune a este efecto si tiene inmunidad al daño cortante, no tiene o no necesita una cabeza, tiene acciones legendarias o tu GM decide que la criatura es demasiado grande como para que esta arma le corte la cabeza. En su lugar, una criatura así recibirá 6d8 de daño cortante adicional por el impacto.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_cfaea569d2e0b0bc$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1cc6fb29854598ed46a65f3c';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1dc5037c519b0370df4df0ea' and md5(to_jsonb(t)::text)='9668df7916bfebeee9b955c3934e3b25')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:1dc5037c519b0370df4df0ea';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_198d9509edfb080a$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando hagas una prueba de Inteligencia (Conocimiento Arcano) para controlar una esfera de aniquilación mientras sostienes este talismán, duplicarás tu bonificador por competencia en la prueba. Además, cuando comiences tu turno con el control de una esfera de aniquilación, podrás usar una acción para hacer que levite 3 m más una cantidad de metros adicionales igual a 3 × tu modificador por Inteligencia.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_198d9509edfb080a$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1dc5037c519b0370df4df0ea';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1e8f4862e932193dfef39183' and md5(to_jsonb(t)::text)='22a47873d0cd307d040d95f0eb37dd9e')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:1e8f4862e932193dfef39183';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_8618753552b3b600$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estos pigmentos, que normalmente se encuentran en 1d4 botes dentro de una elegante caja de madera junto a un pincel (0,5 kg de peso en total), te permi- ten crear objetos tridimensionales al pintarlos en dos dimensiones. La pintura fluye de la brocha para conformar el objeto deseado a medida que te concentras en su imagen.\n\nCada bote de pintura basta para cubrir 90 m2 de una superficie, lo que te permite crear objetos inanimados o accidentes del terreno, como una puerta, un pozo, flores, árboles, celdas, habitaciones o armas, con un volumen total de 280 m3. Se tarda 10 minutos en cubrir 9 m2.\n\nCuando termines de pintar, el objeto o accidente del terreno representado se convertirá en un objeto no mágico real. Por tanto, si pintas una puerta en una pared, crearás una puerta real que pueda abrirse para acceder al otro lado. Si pintas un pozo en el suelo, crearás un pozo real y su profundidad se tendrá en cuenta en el volumen total de los objetos creados.\n\nNinguna creación de los pigmentos puede tener un valor superior a 25 po. Si pintas un objeto de mayor valor (como un diamante o un montón de oro), el objeto parecerá auténtico, pero una inspección minuciosa revelará que está hecho de pasta, hueso u otro material sin valor.\n\nSi dibujas algún tipo de energía, como fuego o un relámpago, aparecerá al completar el dibujo y se esfumará inmediatamente, sin causar daños.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_8618753552b3b600$::jsonb,true),'{rules,personalDescription}',$text_6dcb2cd7e4e4b97e$"Lo normal es encontrar los maravillosos pigmentos de Nolzur como 1d4 botecitos y un pincel dentro de una delicada caja de madera (peso total de 1 libra). Estos pigmentos te permiten crear objetos tridimensionales pintándolos en dos dimensiones. La pintura fluye de la brocha para formar el objeto deseado mientras te concentras en él.\n\nCada bote de pintura es suficiente para cubrir una superficie de 1.000 pies cuadrados, lo que te permite crear objetos inanimados o accidentes del terreno (como una puerta, un pozo, flores, árboles, celdas, habitaciones o armas) con un volumen total de 10.000 pies cúbicos. Tardas 10 minutos en cubrir 100 pies cuadrados.\n\nNinguna creación de los pigmentos puede tener un valor superior a 25 po. Si pintas un objeto de mayor valor (como un diamante o un montón de oro), el objeto parecerá autén tico, pero una inspección detallada revela que está hecho de pasta, hueso u otro material sin valor.\n\nSi dibujas algún tipo de energía, como fuego o relámpago, aparecerá al completar el dibujo y se esfumará inmediata mente, sin dañar a nadie."$text_6dcb2cd7e4e4b97e$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1e8f4862e932193dfef39183';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1f711ae53d9972c65fa8bc6d' and md5(to_jsonb(t)::text)='83e5c5154be8ebfc4e9dee9dea828ace')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:1f711ae53d9972c65fa8bc6d';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_30cb6bdeff7f1a7e$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras embraces este escudo, tendrás resistencia al daño de los ataques con armas a distancia.\n\nMaldición. Este escudo está maldito. Al sintonizarte con él, sufres la maldición hasta que seas el objetivo del conjuro levantar maldición u otro efecto mágico similar. Quitarse el escudo no acaba con la maldición. Cuando se realice un ataque con arma a distancia contra un objetivo a 3 m o menos de ti, la maldición hará que tú te conviertas en el objetivo en su lugar.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_30cb6bdeff7f1a7e$::jsonb,true),'{rules,personalDescription}',$text_cdc793e51e08b04e$"Mientras sostienes este escudo, tienes resistencia al daño de los ataques con armas a distancia.\n\nMaldición. Este escudo está maldito. Sintonizarse con él te maldice hasta que te conviertes en el objetivo del hechizo de quitar maldición o de una magia similar. Quitar el escudo no elimina la maldición que pesa sobre ti. Siempre que se realiza un ataque con un arma a distancia contra un objetivo a menos de 10 pies de ti, la maldición hace que tú te conviertas en el objetivo."$text_cdc793e51e08b04e$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:1f711ae53d9972c65fa8bc6d';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:20072dcfe12c8dff2410a066' and md5(to_jsonb(t)::text)='023605b544c4e520da77e3534ae1b850')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:20072dcfe12c8dff2410a066';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_cf7476881ec925d8$"Objeto · Precio base · Peso\nPergamino (una hoja) · 1 pp · —\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_cf7476881ec925d8$::jsonb,true),'{rules,definition,description}',$text_c36033dfd652106a$[{"id":"official-table","rows":[["Pergamino (una hoja)","1 pp","—"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_c36033dfd652106a$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:20072dcfe12c8dff2410a066';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:204b52f3c4fd93201813054e' and md5(to_jsonb(t)::text)='a43ee055abe7be45c8cc18e23ab9d7f6')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:204b52f3c4fd93201813054e';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_dd50717b3781ab10$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando impactes con un ataque usando esta espada mágica, el objetivo recibirá 1d6 de daño de frío adicional. Además, mientras empuñes la espada, tendrás resistencia al daño de fuego.\n\nEn temperaturas bajo cero, la espada emite luz brillante en un radio de 3 m y luz tenue 3 m más allá.\n\nCuando desenvainas esta arma, puedes extinguir todas las llamas no mágicas que haya a 9 m o menos de ti. Esta propiedad no puede emplearse más de una vez por hora.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_dd50717b3781ab10$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:204b52f3c4fd93201813054e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:21b2968f9cb713fdc704304c' and md5(to_jsonb(t)::text)='eec7698a9a434558d06a7cfddc345e79')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:21b2968f9cb713fdc704304c';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_7a591a866add0bd5$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Si caes mientras llevas puesto este anillo, descenderás 18 m por asalto y no sufrirás daño por la caída.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_7a591a866add0bd5$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:21b2968f9cb713fdc704304c';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:21c4865b127dd7942ad60f2f' and md5(to_jsonb(t)::text)='de527870f3cf1291a740cba032630c30')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:21c4865b127dd7942ad60f2f';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_48d5841a3599e4a7$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes este bastón, podrás utilizar una acción y gastar 1 de sus 10 cargas para lanzar los conjuros entender idiomas, hechizar persona u orden imperiosa desde él con tu CD de salvación de conjuros. El bastón puede utilizarse también como bastón mágico.\n\nSi estás empuñando el bastón y fallas una tirada de salvación contra un conjuro de encantamiento que solo te haga objetivo a ti, podrás superar la tirada fallida en su lugar. No podrás volver a usar esta propiedad hasta el siguiente amanecer. Si superas una tirada de salvación contra un conjuro de encantamiento que solo te haga objetivo a ti, con o sin la intervención del bastón, podrás utilizar tu reacción y gastar 1 carga del bastón para volver el conjuro en contra de su lanzador como si tú lo hubieras lanzado.\n\nEl bastón recupera 1d8 + 2 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón se convierte en un bastón no mágico.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_48d5841a3599e4a7$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:21c4865b127dd7942ad60f2f';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:228455e6c8f12bf61d32bd0f' and md5(to_jsonb(t)::text)='ffb02e55650c54df80589356b99f98bf')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:228455e6c8f12bf61d32bd0f';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_8fc51420d0024709$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta delicada prenda se ha fabricado con seda negra y tiene finas hebras plateadas entretejidas. Mientras la lleves puesta, obtendrás los siguientes beneficios: • Tienes resistencia al daño de veneno. • Tienes una velocidad trepando igual a tu velocidad caminando. • Puedes moverte hacia arriba, hacia abajo y de lado por superficies verticales, así como boca abajo por techos. Esta manera de moverse no requiere del uso de las manos, que quedan libres. • No puedes quedar atrapado en ningún tipo de red o telaraña y podrás moverte por ellas como si fueran terreno difícil. • Puedes usar una acción para lanzar el conjuro telaraña (CD de salvación 13). La telaraña creada por este conjuro tiene el doble del tamaño normal. Una vez utilizada, esta propiedad de la capa no puede volver a usarse hasta el siguiente amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_8fc51420d0024709$::jsonb,true),'{rules,personalDescription}',$text_f031c2d729f72f24$"Esta delicada prenda está tejida con seda negra y tiene finas hebras plateadas entretejidas. Mientras la lleves, obtendrás los siguientes beneficios:\n<brResistencia al daño de veneno.\nUna velocidad trepando igual a tu velocidad caminando.\nPodrás moverte hacia arriba, hacia abajo y por superfi cies verticales, así como colgarte del techo. Puedes realizar todos estos movimientos mientras mantienes tus manos libres.\nNo puedes quedar atrapado en ningún tipo deredes o telarañas, y serás capaz de moverte a través de ellas como si fueran terreno difícil.\nPuedes usar una acción para lanzar el conjuro telaraña (CD de salvación 13). La telaraña creada por este conjuro tiene el doble del tamaño normal. Esta propiedad de la capa no puede volver a emplearse hasta el siguiente amanecer."$text_f031c2d729f72f24$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:228455e6c8f12bf61d32bd0f';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2332efbe842bef596b4af269' and md5(to_jsonb(t)::text)='812663d27e3c0d3d997bff09daf2d386')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:2332efbe842bef596b4af269';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_3d20682e3808f6a0$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para soplar este cuerno. Como respuesta, varios espíritus guerreros del Valhalla aparecerán a 18 m o menos de ti. Utilizan el perfil del berserker. Regresarán al Valhalla después de 1 hora o cuando sus puntos de golpe se reduzcan a 0. Una vez que utilices el cuerno, no podrás volver a usarlo hasta que hayan pasado 7 días.\n\nSe conoce la existencia de cuatro tipos de cuerno del Valhalla, cada uno hecho de un metal distinto. El tipo de cuerno determina cuántos berserkers responden a su llamada, así como el requisito para utilizarlo. Tu GM elige el tipo de cuerno o lo determina al azar.\n\n01–40 · Plata · 2d4 + 2 · Ninguno\n41–75 · Oropel · 3d4 + 3 · Competencia con todas las armas sencillas\n76–90 · Bronce · 4d4 + 4 · Competencia con todas las armaduras medias\n91–00 · Hierro · 5d4 + 5 · Competencia con todas las armas marciales\n\nSi soplas el cuerno sin cumplir su requisito, los berserkers invocados te atacarán. Si cumples el requisito, serán amistosos contigo y tus compañeros, y seguirán tus órdenes.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3d20682e3808f6a0$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2332efbe842bef596b4af269';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2332f606e84baed04abe564c' and md5(to_jsonb(t)::text)='15dfe178c31f49257d5dc2f7536931f2')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:2332f606e84baed04abe564c';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_b40b5f9186ea5148$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes un bonificador a las tiradas de ataque y de daño que hagas con esta unidad de munición mágica. El bonificador depende de la rareza de la munición. Una vez que impacte en un objetivo, la munición dejará de ser mágica.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b40b5f9186ea5148$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2332f606e84baed04abe564c';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:234d31692db9f12b1e42dbb2' and md5(to_jsonb(t)::text)='762c44d49f001c9d97aa179e7a079c83')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:234d31692db9f12b1e42dbb2';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_2467095af0cbf025$"Objeto · Precio base · Peso\nSuministros de cervecero · 20 po · 9 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_2467095af0cbf025$::jsonb,true),'{features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{rules,definition,description}',$text_088f854cd8c99670$[{"id":"official-table","rows":[["Suministros de cervecero","20 po","9 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_088f854cd8c99670$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:234d31692db9f12b1e42dbb2';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:23abf7f292bc7bc0f40d9f43' and md5(to_jsonb(t)::text)='37aaec741bc4bd9a3a6f40a374cf7b1b')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:23abf7f292bc7bc0f40d9f43';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_977e20479b0599c5$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este cubo mide aproximadamente 2,5 cm de lado. Cada cara tiene un signo específico que puede pulsarse. El cubo comienza con 36 cargas y recupera 1d20 cargas empleadas cada día, al amanecer.\n\nPuedes usar una acción para pulsar una de las caras del cubo y gastar una cantidad de cargas que dependerá de la cara en cuestión, tal y como se muestra en la tabla “Caras del cubo de fuerza”. Cada cara tiene un efecto diferente. Si al cubo no le quedan suficientes cargas, no ocurrirá nada. En caso contrario, surgirá una barrera de fuerza invisible que formará un cubo de 4,5 m de lado. La barrera se centra en ti, se mueve contigo y dura 1 minuto, hasta que emplees una acción para pulsar la sexta cara del cubo o hasta que el cubo se quede sin cargas. Puedes cambiar el efecto de la barrera si pulsas otra cara del cubo y gastas la cantidad necesaria de cargas, lo que reiniciará la duración.\n\nSi tu movimiento hace que la barrera entre en contacto con un objeto sólido que no pueda atravesar el cubo, no serás capaz de acercarte más a ese objeto hasta que la barrera deje de existir. Caras del cubo de fuerza\n\n1 · 1 · Los gases, el viento y la niebla no pueden atravesar la barrera.\n2 · 2 · La materia inerte no puede atravesar la barrera. Los muros, suelos y techos pueden atravesarla a tu discreción.\n3 · 3 · La materia viva no puede atravesar la barrera.\n4 · 4 · Los efectos de conjuros no pueden atravesar la barrera.\n5 · 5 · Nada puede atravesar la barrera. Los muros, suelos y techos pueden atravesarla a tu discreción.\n6 · 0 · La barrera se desactiva.\n\nEl cubo pierde cargas cuando la barrera es el objetivo de determinados conjuros o entra en contacto con los efectos de ciertos conjuros u objetos mágicos, tal y como se muestra en la tabla siguiente.\n\nCuerno de estallido · 1d10\nDesintegrar · 1d12\nMuro de fuego · 1d4\nPasamuros · 1d6\nRociada prismática · 1d20\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_977e20479b0599c5$::jsonb,true),'{rules,personalDescription}',$text_bb4f8b70f9abd311$"Este cubo mide una pulgada de lado. Cada cara tiene un signo específico, que puede ser pulsado. El cubo comienza con 36 cargas y recupera l d20 cargas cada día, al amanecer. Puedes usar una acción para pulsar una de las caras del cubo, gastando un número de cargas que depende de la cara en cuestión, como se muestra en la tabla caras del cubo de fuerza. Cada cara posee un efecto distinto. Si al cubo no le quedan suficientes cargas, no pasa nada. En caso contrario, surge una barrera de fuerza invisible, formando un cubo de 15 pies de lado. La barrera está centrada en ti, se mueve contigo y dura 1 minuto, hasta que emplees una acción para presionar la sexta cara del cubo o hasta que este se quede sin cargas. Puedes cambiar el efecto de la barrera presionando una cara distinta del cubo y gastando el número de cargas requerido, lo que reinicia la duración. Si tu movimiento hace que la barrera entre en contacto con un objeto sólido que no pueda atravesar el cubo, no serás capaz de acercarte más a ese objeto hasta que la barrera deje de existir.\n\n1 - 1 - Los gases, vientos y nieblas no pueden atravesar la barrera.\n2 - 2 - La materia inerte no puede atravesar la barrera. Muros, suelos y techos pueden cruzarla a tu discreción.\n3 - 3 - La materia viva no puede atravesar la barrera.\n4 - 4 - Los efectos de conjuros no pueden atravesar la barrera.\n5 - 5 - Nada puede atravesar la barrera. Muros, suelos y techos pueden cruzarla a tu discreción.\n6 - 0 - La barrera se desactiva\n\nEl cubo pierde cargas cuando la barrera es objetivo de ciertos conjuros o entra en contacto con algunos efectos de conj uros u objetos mágicos, como se muestra en la siguiente tabla.\n\nDesintegrar - 1d12\nCuerno de estallido - 1d10\nPasamuros - 1d6\nRociada prismática - 1d20\nMuro de fuego- 1d4"$text_bb4f8b70f9abd311$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:23abf7f292bc7bc0f40d9f43';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:23f23e21a5e68c1fae048f09' and md5(to_jsonb(t)::text)='5c73066e0a1278d806245605cb8c7050')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:23f23e21a5e68c1fae048f09';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_4a48d0c039253fa2$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes usar una acción adicional para lanzar esta espada mágica al aire y pronunciar la palabra de activación. Cuando lo hagas, el arma comenzará a levitar, volará hasta 9 m y atacará a una criatura de tu elección que esté a 1,5 m o menos de ella. La espada utiliza tu tirada de ataque y tu modificador por característica para las tiradas de daño.\n\nMientras la espada esté levitando, podrás emplear una acción adicional para que vuele hasta 9 m hacia otro lugar situado a 9 m o menos de ti. Como parte de la misma acción adicional, podrás hacer que la espada ataque a una criatura situada a 1,5 m o menos de ella.\n\nDespués de que la espada flotante ataque por cuarta vez, volará hasta 9 m y tratará de regresar a tu mano. Si no tienes ninguna mano libre, caerá a tus pies. Si la espada tiene vía libre hasta ti, se te acercará todo lo que pueda y después caerá al suelo. También dejará de levitar si la agarras o si te alejas más de 9 m de ella.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4a48d0c039253fa2$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:23f23e21a5e68c1fae048f09';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:240e4ce5f914087a513da6a2' and md5(to_jsonb(t)::text)='6abdf21691eae75f4200f3034d1bc0d4')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:240e4ce5f914087a513da6a2';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_f3ae9b4fecfd8020$"Objeto · Precio base · Peso\nCantimplora · 2 pp · 5 lb (llena)\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_f3ae9b4fecfd8020$::jsonb,true),'{rules,definition,description}',$text_0ad7a883d022e3a3$[{"id":"official-table","rows":[["Cantimplora","2 pp","5 lb (llena)"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_0ad7a883d022e3a3$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:240e4ce5f914087a513da6a2';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:24a89eb8efb8617f0eecf7e4' and md5(to_jsonb(t)::text)='dbd20f7122e7e662a5d6e1d8110e50e7')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:24a89eb8efb8617f0eecf7e4';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_6f7347b1b4da5195$[{"id":"withering-hit","kind":"other","name":"Marchitamiento","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"2d10"}],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"Este bastón tiene 3 cargas y recupera 1d3 cargas empleadas cada día, al amanecer.\n\nEl bastón se puede usar a modo de bastón mágico. Si impactas con él, causa daño como un bastón normal y puedes gastar 1 carga para infligir 2d10 de daño necrótico adicional al objetivo. Además, el objetivo deberá superar una tirada de salvación de Constitución con CD 15 o tendrá desventaja durante 1 hora en cualquier prueba de característica o tirada de salvación que utilice la Fuerza o la Constitución.\n\nDuración: 1 hora para la desventaja; el daño es inmediato..\n\nCoste: 1 cargas.","showInActions":false}]$text_6f7347b1b4da5195$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:24a89eb8efb8617f0eecf7e4';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:250884d74945e41176af6df1' and md5(to_jsonb(t)::text)='f3c5da2074ea198f5762759313235e7b')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:250884d74945e41176af6df1';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_b40b5f9186ea5148$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes un bonificador a las tiradas de ataque y de daño que hagas con esta unidad de munición mágica. El bonificador depende de la rareza de la munición. Una vez que impacte en un objetivo, la munición dejará de ser mágica.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b40b5f9186ea5148$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:250884d74945e41176af6df1';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2576abf7d0b4aa35a244426d' and md5(to_jsonb(t)::text)='bdc5cfd621e0b5a7d1b18a2695d3b31c')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:2576abf7d0b4aa35a244426d';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_4ca76cc6ddf1af62$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia a un tipo de daño mientras lleves esta armadura. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4ca76cc6ddf1af62$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2576abf7d0b4aa35a244426d';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:25c626a208ba4a32f000c0d0' and md5(to_jsonb(t)::text)='2a2290e9758c335a02e74f297e5f39cf')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:25c626a208ba4a32f000c0d0';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_29a45bdffabc85d9$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto del conjuro clarividencia. En este líquido amarillento flota un globo ocular, pero desaparece en cuanto se abre la poción.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_29a45bdffabc85d9$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:25c626a208ba4a32f000c0d0';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:25d11d7b5a7b5c94a5f9c0c8' and md5(to_jsonb(t)::text)='f473bbb672acbd0c8a48fe10fea63fb0')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:25d11d7b5a7b5c94a5f9c0c8';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_7b31b792807934b9$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, tendrás resistencia a un tipo de daño. La gema incrustada en el anillo, que tu GM elige o determina al azar, indica el tipo de daño.\n\n1 · Ácido · Perla\n2 · Frío · Turmalina\n3 · Fuego · Granate\n4 · Fuerza · Zafiro\n5 · Necrótico · Azabache\n6 · Psíquico · Jade\n7 · Radiante · Topacio\n8 · Relámpago · Citrino\n9 · Trueno · Espinela\n10 · Veneno · Amatista\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_7b31b792807934b9$::jsonb,true),'{rules,personalDescription}',$text_6075c158ee2d28a5$"Tienes resistencia a un tipo de daño mientras llevas este anillo. La gema del anillo indica el tipo, que el DM elige o determina aleatoriamente.\n-1-Acido-Perla\n-2-Frio-Turmalina\n-3-Fuego-Granate\n-4-Fuerza-Zafiro\n-5-Relámpago-Citrino\n-6-Necrótico-Azabache.\n-7-Veneno-Amatista\n-8-Psíquico-Jade\n-9-Radiante-Topacio\n-10-Trueno-Espinela"$text_6075c158ee2d28a5$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:25d11d7b5a7b5c94a5f9c0c8';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:27449e1bed6d4f91099fb4e4' and md5(to_jsonb(t)::text)='e410174a5c89bd86de39274215ee6965')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:27449e1bed6d4f91099fb4e4';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_098e651649ff7d4d$[{"id":"mundane-assisted-use","kind":"other","name":"Jugar con competencia","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Set de Juego. Este objeto engloba un amplio rango de piezas de juego incluyendo dados y barajas de cartas (para juegos tales como Tres dragones). Unos pocos ejemplos comunes aparecen en la tabla Herramientas pero existen otro tipo de sets de juego. Si eres competente con un set de juego puedes añadir tu bonificador de competencia a las pruebas de característica que realices para jugar a un juego con este set. Cada tipo de set de juego requiere una competencia por separado.\n\nDuración: Según su uso..","showInActions":false}]$text_098e651649ff7d4d$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:27449e1bed6d4f91099fb4e4';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:283d43a7fbb28f2f5d081a4d' and md5(to_jsonb(t)::text)='33acfe13c1afe34cba724508e4545937')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:283d43a7fbb28f2f5d081a4d';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_9e343969c674a850$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción para gastar 1 de sus cargas y elegir un objetivo a 36 m o menos de ti. El objetivo puede ser una criatura, un objeto o un punto en el espacio. Tira 1d100 y consulta la tabla que aparece a continuación para descubrir lo que ocurrirá.\n\nSi el efecto hace que lances un conjuro con la varita, la CD de salvación será 15. Si el conjuro tiene normalmente un alcance expresado en metros, su alcance pasará a ser de 36 m (si no lo era ya).\n\nSi un efecto cubre un área, deberás centrar el conjuro en el objetivo e incluirlo en su interior. Si un efecto tiene varios objetivos posibles, tu GM determinará al azar cuáles se verán afectados.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en polvo y se destruye.\n\n01–05 · Lanzas ralentizar.\n06–10 · Lanzas fuego feérico.\n11–15 · Crees que algo asombroso acaba de ocurrir, por lo que te quedas aturdido hasta el principio de tu siguiente turno.\n16–20 · Lanzas ráfaga de viento.\n21–25 · Lanzas detectar pensamientos sobre el objetivo que elijas. Si no has hecho objetivo a una criatura, en vez de eso, recibirás 1d6 de daño psíquico.\n26–30 · Lanzas nube apestosa.\n31–33 · Una lluvia intensa cae en un radio de 18 m centrado en el objetivo. La zona se vuelve ligeramente oscura. La lluvia cae hasta el principio de tu siguiente turno.\n34–36 · Un animal aparece en el espacio sin ocupar más cercano al objetivo. El animal no se encuentra bajo tu control y actúa con normalidad. Tira 1d100 para determinar qué animal aparece. Si el resultado es 01-25, aparecerá un rinoceronte; si es 26-50, aparecerá un elefante, y con 51-100, aparecerá una rata.\n37–46 · Lanzas relámpago.\n47–49 · Una nube de 600 mariposas de gran tamaño cubre un radio de 9 m centrado en el objetivo. La zona se vuelve muy oscura. Las mariposas permanecen durante 10 minutos.\n50–53 · Aumentas el tamaño del objetivo como si hubieras lanzado agrandar/reducir. Si el objetivo no puede verse afectado por ese conjuro o si no has hecho objetivo a una criatura, tú te convertirás en el objetivo.\n54–58 · Lanzas oscuridad.\n59–62 · La hierba crece en el suelo en un radio de 18 m centrado en el objetivo. Si ya había hierba allí, crecerá hasta diez veces su tamaño normal y tendrá ese tamaño durante 1 minuto.\n63–65 · Un objeto a elección de tu GM desaparece en el Plano Etéreo. El objeto no puede medir más de 3 m en ninguna dimensión, debe encontrarse a 36 m o menos del objetivo y nadie puede vestirlo o llevarlo.\n66–69 · Encoges como si hubieras lanzado agrandar/reducir sobre ti.\n70–79 · Lanzas bola de fuego.\n80–84 · Lanzas invisibilidad sobre ti.\n85–87 · Crecen hojas en el objetivo. Si eliges un punto en el espacio como objetivo, las hojas brotan de la criatura más cercana a ese punto. Salvo que se arranquen, las hojas se volverán marrones y caerán tras 24 horas.\n88–90 · Una ráfaga de 1d4 × 10 gemas, cada una con un valor de 1 po, sale disparada de la punta de la varita en una línea de 9 m de largo y 1,5 m de ancho. Cada gema hace 1 de daño contundente y el total de daño de las gemas se divide a partes iguales entre todas las criaturas situadas en la línea.\n91–95 · Una explosión de luz resplandeciente y colorida se extiende desde ti en un radio de 9 m. Todas las criaturas que puedan ver en el área y tú deberéis superar una tirada de salvación de Constitución con CD 15 o quedaréis cegados durante 1 minuto. Una criatura puede repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto.\n96–97 · La piel del objetivo se vuelve azul brillante durante 1d10 días. Si has elegido un punto en el espacio como objetivo, la criatura más cercana a ese punto será quien sufra el efecto.\n98–00 · Si tu objetivo es una criatura, deberá hacer una tirada de salvación de Constitución con CD 15. Si no has hecho objetivo a una criatura, tú te convertirás en el objetivo y deberás hacer la tirada de salvación. Si la falla por 5 o más, el objetivo quedará petrificado instantáneamente. Si la falla con otro resultado, el objetivo quedará apresado y comenzará a convertirse en piedra. Mientras el objetivo esté apresado de esta forma, deberá repetir la tirada de salvación al final de su siguiente turno; quedará petrificado si la falla o se librará del efecto si la supera. La petrificación dura hasta que el objetivo sea liberado mediante un conjuro restablecimiento mayor u otro efecto mágico similar.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_9e343969c674a850$::jsonb,true),'{rules,personalDescription}',$text_109e450eded382da$"Esta varita tiene 7 cargas. Mientras la sostienes, puedes usar una acción para gastar 1 de sus cargas y elegir un objetivo a 120 pies o menos de ti. El objetivo puede ser una criatura, un objeto o un punto en el espacio. Tira d100 y consulta la siguiente tabla para descubrir qué sucede. Si el efecto hace que lances un hechizo desde la varita, la CD de salvación del hechizo es 15. Si el hechizo normalmente tiene un alcance expresado en pies, su alcance se convierte en 120 pies si no lo es ya. Si un efecto cubre un área, debes centrar el hechizo en el objetivo e incluirlo. Si un efecto tiene múltiples objetivos posibles, el DM determina aleatoriamente cuáles son los afectados.\n\nLa varita recupera 1d6 + 1 de las cargas gastadas diariamente al amanecer. Si gastas la última carga de la varita, tira 1d20. Con un 1, la varita se deshace en polvo y queda destruida.\n\n01-05 - Lanzas lento.\n06-10 - Lanzas fuego feérico.\n11-15 - Quedas aturdido hasta el comienzo de tu siguiente turno, creyendo que algo increíble acaba de suceder.\n16-20 - Lanzas ráfaga de viento.\n21-25 - Lanzas la habilidad de detectar pensamientos al objetivo que hayas elegido. Si no elegiste a una criatura, recibes 1d6 de daño psíquico.\n26-30 - Lanzas una nube apestosa.\n31-33 - Cae una lluvia intensa en un radio de 60 pies centrado en el objetivo. El área queda ligeramente oscurecida. La lluvia cae hasta el comienzo de tu siguiente turno.\n34-36 - Aparece un animal en el espacio desocupado más cercano al objetivo. El animal no está bajo tu control y actúa como lo haría normalmente. Tira 1d100 para determinar qué animal aparece. Con un 01/25, aparece un rinoceronte; con un 26/50, aparece un elefante; y con un 51/100, aparece una rata.\n37-46 - Lanzas rayo.\n47-49 - Una nube de 600 mariposas gigantes llena un radio de 30 pies centrado en el objetivo. El área queda muy oscura. Las mariposas permanecen allí durante 10 minutos.\n50-53 - Agrandas el objetivo como si hubieras lanzado agrandar/reducir. Si el objetivo no puede verse afectado por ese hechizo, o si no elegiste a ninguna criatura como objetivo, te conviertes en el objetivo.\n54-58 - Arrojas oscuridad.\n59-62 - La hierba crece en el suelo en un radio de 60 pies centrado en el objetivo. Si ya hay hierba allí, crece hasta alcanzar diez veces su tamaño normal y permanece cubierta de maleza durante 1 minuto.\n63-65 - Un objeto elegido por el DM desaparece en el Plano Etéreo. El objeto no debe llevarse puesto ni llevarse en un radio de 120 pies del objetivo y no debe medir más de 10 pies en ninguna dimensión.\n66-69 - Te encoges como si te hubieras lanzado agrandar/reducir.\n70-79 - Lanzas bola de fuego.\n80-84 - Te lanzas invisibilidad a ti mismo.\n85-87 - Las hojas crecen del objetivo. Si eliges un punto en el espacio como objetivo, las hojas brotan de la criatura más cercana a ese punto. A menos que las arranques, las hojas se vuelven marrones y se caen después de 24 horas.\n88-90 - Un chorro de 1d4 × 10 gemas, cada una de ellas con un valor de 1 po, sale disparado desde la punta de la varita en una línea de 30 pies de largo y 5 pies de ancho. Cada gema inflige 1 punto de daño contundente, y el daño total de las gemas se divide equitativamente entre todas las criaturas de la línea. 91-95 - Una explosión de luz brillante y colorida se extiende desde ti en un radio de 30 pies. Tú y cada criatura en el área que pueda ver deben tener éxito en una tirada de salvación de Constitución CD 15 o quedarán cegados durante 1 minuto. Una criatura puede repetir la tirada de salvación al final de cada uno de sus turnos, terminando el efecto sobre sí misma si tiene éxito.\n96-97 - La piel del objetivo se vuelve azul brillante durante 1d10 días. Si elegiste un punto en el espacio, la criatura más cercana a ese punto se ve afectada. 98-00 - Si elegiste a una criatura, esta debe realizar una tirada de salvación de Constitución CD 15. Si no elegiste a una criatura, tú te conviertes en el objetivo y debes realizar la tirada de salvación. Si la tirada de salvación falla por 5 o más, el objetivo queda petrificado instantáneamente. Si falla cualquier otra tirada de salvación, el objetivo queda inmovilizado y comienza a convertirse en piedra. Mientras está inmovilizado de esta manera, el objetivo debe repetir la tirada de salvación al final de su siguiente turno, quedando petrificado si falla o terminando el efecto si tiene éxito. La petrificación dura hasta que el objetivo es liberado por el conjuro de restauración mayor o magia similar."$text_109e450eded382da$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:283d43a7fbb28f2f5d081a4d';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:285015c1f803ed9cd52a94c8' and md5(to_jsonb(t)::text)='a68a2d6a9ae68071637e194d15ab40d9')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:285015c1f803ed9cd52a94c8';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_1d722e423b49351b$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 de sus cargas para conjurar un delgado rayo azul que serpenteará desde la punta de la varita hacia una criatura que puedas ver a 18 m o menos de ti. El objetivo deberá superar una tirada de salvación de Constitución con CD 15 o quedará paralizado durante 1 minuto. Podrá repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_1d722e423b49351b$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:285015c1f803ed9cd52a94c8';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:288b0e63563a7d6ecda0925b' and md5(to_jsonb(t)::text)='beacd9d06de9c6952e2fff6d39170254')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:288b0e63563a7d6ecda0925b';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_e1f13f389bea68e5$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás resistencia a un tipo de daño durante 1 hora. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_e1f13f389bea68e5$::jsonb,true),'{rules,personalDescription}',$text_6cae00f70201c866$"Cuando bebes esta poción, obtienes resistencia a un tipo de daño durante 1 hora. El DM elige el tipo o lo determina aleatoriamente tirando en la siguiente tabla.\n1-Acido\n2-Frio\n3-Fuego\n4-Fuerza\n5-Relampago\n6-Necrotico\n7-Veneno\n8-Psíquico\n9-Radiante\n10-Trueno"$text_6cae00f70201c866$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:288b0e63563a7d6ecda0925b';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:28901ef2614cdb26e4f09af0' and md5(to_jsonb(t)::text)='0b6b1d2731515e73158ac76adcd20b39')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:28901ef2614cdb26e4f09af0';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_6831ba56f10b63d2$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"La próxima vez que veas a una criatura en los 10 minutos posteriores a beber este filtro, quedarás hechizado por ella durante 1 hora. Si la criatura es de una especie y género que normalmente te atraigan, la considerarás tu amor verdadero mientras permanezcas hechizado. El líquido efervescente y de tonalidad rosa de este brebaje contiene una burbuja, fácil de pasar por alto, con forma de corazón.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_6831ba56f10b63d2$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:28901ef2614cdb26e4f09af0';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:29b91b0b62ab8ab131ddf0b1' and md5(to_jsonb(t)::text)='9877d2989ccbd7bc9644bdb6b5b739a5')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:29b91b0b62ab8ab131ddf0b1';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_657c259537dee184$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta capa con la capucha puesta, podrás respirar bajo el agua y tendrás una velocidad nadando de 18 m. Ponerte o quitarte la capucha requiere una acción.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_657c259537dee184$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:29b91b0b62ab8ab131ddf0b1';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2b27121f4f6b49d06be83a0b' and md5(to_jsonb(t)::text)='475b156379e06e763dbdd13e518e2e71')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:2b27121f4f6b49d06be83a0b';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_4ca76cc6ddf1af62$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia a un tipo de daño mientras lleves esta armadura. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4ca76cc6ddf1af62$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2b27121f4f6b49d06be83a0b';

update public.campaigns set state_revision=state_revision+1,state_updated_at=statement_timestamp(),updated_at=statement_timestamp() where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd';end $text$;select 2 as batch,39 as rows,(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')as revision;commit;